import torch
import torch.nn as nn

class DeepHedgingAgent(nn.Module):
    def __init__(self, input_dim=3, hidden_dim=32):
        super().__init__()
        # Inputs: [log_moneyness, time_to_maturity, current_holding]
        self.network = nn.Sequential(
            nn.Linear(input_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, hidden_dim),
            nn.ReLU(),
            nn.Linear(hidden_dim, 1),
            nn.Tanh() # Outputs target hedge ratio in [-1, 1]
        )

    def forward(self, state):
        return self.network(state)

def entropic_loss(terminal_pnl, risk_aversion=1.0):
    # Measures expected exponential utility: E[exp(-lambda * PnL)]
    return torch.log(torch.mean(torch.exp(-risk_aversion * terminal_pnl))) / risk_aversion
